CREATE TYPE "Role" AS ENUM ('CUSTOMER', 'PARTNER', 'COURIER', 'ADMIN');
CREATE TYPE "PartnerStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED', 'SUSPENDED');
CREATE TABLE "User" ("id" UUID PRIMARY KEY, "phone" VARCHAR(32) NOT NULL UNIQUE, "locale" VARCHAR(8) NOT NULL DEFAULT 'ru', "displayName" VARCHAR(160), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "UserRole" ("userId" UUID NOT NULL, "role" "Role" NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY ("userId", "role"), CONSTRAINT "UserRole_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE TABLE "OtpChallenge" ("id" UUID PRIMARY KEY, "phone" VARCHAR(32) NOT NULL, "codeDigest" CHAR(64) NOT NULL, "attempts" INTEGER NOT NULL DEFAULT 0, "maxAttempts" INTEGER NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "userId" UUID, CONSTRAINT "OtpChallenge_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE INDEX "OtpChallenge_phone_createdAt_idx" ON "OtpChallenge"("phone", "createdAt");
CREATE TABLE "Session" ("id" UUID PRIMARY KEY, "userId" UUID NOT NULL, "familyId" UUID NOT NULL, "refreshDigest" CHAR(64) NOT NULL, "expiresAt" TIMESTAMP(3) NOT NULL, "revokedAt" TIMESTAMP(3), "replacedById" UUID, "reuseDetectedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Session_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE INDEX "Session_userId_familyId_idx" ON "Session"("userId", "familyId");
CREATE TABLE "Partner" ("id" UUID PRIMARY KEY, "ownerId" UUID NOT NULL UNIQUE, "displayName" VARCHAR(180) NOT NULL, "status" "PartnerStatus" NOT NULL DEFAULT 'PENDING', "approvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Partner_ownerId_fkey" FOREIGN KEY ("ownerId") REFERENCES "User"("id") ON DELETE RESTRICT);
CREATE TABLE "Branch" ("id" UUID PRIMARY KEY, "partnerId" UUID NOT NULL, "name" VARCHAR(180) NOT NULL, "city" VARCHAR(100) NOT NULL DEFAULT 'Tashkent', "district" VARCHAR(120), "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Branch_partnerId_fkey" FOREIGN KEY ("partnerId") REFERENCES "Partner"("id") ON DELETE CASCADE);
CREATE TABLE "AuditEvent" ("id" UUID PRIMARY KEY, "actorId" UUID, "eventType" VARCHAR(80) NOT NULL, "targetType" VARCHAR(50), "metadata" JSONB NOT NULL DEFAULT '{}', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_actorId_fkey" FOREIGN KEY ("actorId") REFERENCES "User"("id") ON DELETE SET NULL);
CREATE INDEX "AuditEvent_eventType_createdAt_idx" ON "AuditEvent"("eventType", "createdAt");
CREATE TABLE "BootstrapState" ("key" VARCHAR(50) PRIMARY KEY, "usedAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
